import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.CqGPl1zp.js";const m=JSON.parse('{"title":"工作流（达梦适配）","description":"","frontmatter":{},"headers":[],"relativePath":"bpm/dameng.md","filePath":"bpm/dameng.md","lastUpdated":null}'),d={name:"bpm/dameng.md"};function r(l,e,c,i,n,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="工作流-达梦适配" tabindex="-1">工作流（达梦适配） <a class="header-anchor" href="#工作流-达梦适配" aria-label="Permalink to &quot;工作流（达梦适配）&quot;">​</a></h1><p>达梦的适配，分成两种版本，按需使用：</p><ul><li>如果你是 <code>master</code> 分支，参考「1. 适配 <code>分支</code>」小节。</li><li>如果你是 <code>master-jdk17</code> 分支，参考「2. 适配 <code>master-jdk17</code> 分支」小节。</li></ul><h2 id="_1-适配-master-分支" tabindex="-1">1. 适配 <code>master</code> 分支 <a class="header-anchor" href="#_1-适配-master-分支" aria-label="Permalink to &quot;1. 适配 `master` 分支&quot;">​</a></h2><p>友情提示：</p><p>本文参考 <a href="https://blog.csdn.net/TangBoBoa/article/details/130392495" target="_blank" rel="noreferrer">《Flowable6.8(6.x 版本通用)整合集成达梦 8 数据库(DM8)详解，解决自动生成表时 dmn 相关表语法报错问题》</a> 博客，由开发者（微信号 <code>barry82</code>）所贡献！</p><h3 id="_1-1-覆盖-flowable-liquibase-相关代码" tabindex="-1">1.1 覆盖 Flowable Liquibase 相关代码 <a class="header-anchor" href="#_1-1-覆盖-flowable-liquibase-相关代码" aria-label="Permalink to &quot;1.1 覆盖 Flowable Liquibase 相关代码&quot;">​</a></h3><p>把项目的 <code>sql/dm/flowable-patch/src</code> 下的文件，复制到 <code>yudao-module-bpm</code> 项目的 <code>src</code> 目录中。</p><h3 id="_1-2-关于-flowable-database-schema-update-配置" tabindex="-1">1.2 关于 flowable.database-schema-update 配置 <a class="header-anchor" href="#_1-2-关于-flowable-database-schema-update-配置" aria-label="Permalink to &quot;1.2 关于 flowable.database-schema-update 配置&quot;">​</a></h3><p>① 首次运行，全局搜 <code>flowable.database-schema-update</code> 配置项，修改为 <code>true</code>，以便生成 Flowable 数据库表。</p><p>② 再次运行，全局搜 <code>flowable.database-schema-update</code> 配置项，修改为 <code>false</code>，避免如下报错：</p><div class="language-Bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [FLW_EV_DATABASECHANGELOG] already exists</span></span></code></pre></div><hr><p>ps：😭 MacBook 从 Intel 平台迁移到 M1 平台，达梦数据库的环境坏了，先暂时把相关的操作写到文档里，算是给大家做适配一个方向！</p><h2 id="_2-适配-master-jdk17-分支" tabindex="-1">2. 适配 <code>master-jdk17</code> 分支 <a class="header-anchor" href="#_2-适配-master-jdk17-分支" aria-label="Permalink to &quot;2. 适配 `master-jdk17` 分支&quot;">​</a></h2><p>如果你是 <code>master-jdk17</code> 分支，需要额外参考 <a href="https://t.zsxq.com/sXvQ8" target="_blank" rel="noreferrer">https://t.zsxq.com/sXvQ8</a> 文档，保持耐心~</p><p>另外，也可以直接合并 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/tree/master-dm8-jdk17" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro/tree/master-dm8-jdk17</a> 分支，已经验证过。</p>',17)])])}const b=a(d,[["render",r]]);export{m as __pageData,b as default};
